const projects=[
 {title:"GridFM 2.0",summary:"Brookhaven-led effort using artificial intelligence to accelerate electric-grid planning; linked to a DOE $11.5 million project announcement.",url:"https://www.energy.gov/oe/articles/does-office-electricity-announces-115m-genesis-mission-project-meet-growing-electricity",date:"2026-09-01",source:"Brookhaven / DOE",category:"Infrastructure",tier:"Official",kind:"project",organization:"Brookhaven National Laboratory"},
 {title:"AI4HPC",summary:"Argonne-led AI-assisted scientific software development and optimization, cited in DOE's October 2026 award announcement.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"Argonne / DOE",category:"AI models",tier:"Official",kind:"project",organization:"Argonne National Laboratory"},
 {title:"MOAT-Core",summary:"Berkeley-led shared AI platform supporting accelerator science.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"Berkeley / DOE",category:"AI models",tier:"Official",kind:"project",organization:"Berkeley Lab"},
 {title:"MAESTRO",summary:"AI reasoning and optimization for geothermal-reservoir research; UC Irvine-led.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"UC Irvine / DOE",category:"National challenges",tier:"Official",kind:"project",organization:"University of California, Irvine"},
 {title:"AXESS",summary:"AI-enabled design of microchips for extreme environments; Fermilab-led.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"Fermilab / DOE",category:"National challenges",tier:"Official",kind:"project",organization:"Fermilab"},
 {title:"AI-assisted quantum magnet design",summary:"Oak Ridge-led research into quantum materials with desired magnetic properties.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"ORNL / DOE",category:"AI models",tier:"Official",kind:"project",organization:"Oak Ridge National Laboratory"}
];
const announcements=[
 {title:"DOE announces additional Genesis Mission Phase II awards",summary:"DOE announced 12 new Phase II awards totaling $159 million and described a first-year portfolio of 297 projects.",date:"2026-10-08",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",source:"DOE",category:"National challenges",tier:"Official",kind:"news"},
 {title:"ORNL selected for six Phase II Genesis awards",summary:"Laboratory awards span materials, microelectronics, quantum computing, accelerator software and fusion.",date:"2026-10-08",url:"https://www.ornl.gov/news/ornl-selected-for-six-phase-ii-genesis-mission-awards/",source:"ORNL",category:"AI models",tier:"Related",kind:"news"}
];
const labs=[["DOE","https://www.energy.gov/"],["Genesis Mission","https://genesis.energy.gov/"],["Oak Ridge","https://www.ornl.gov/"],["Argonne","https://www.anl.gov/"],["Brookhaven","https://www.bnl.gov/"],["Berkeley Lab","https://www.lbl.gov/"],["Los Alamos","https://www.lanl.gov/"],["Pacific Northwest","https://www.pnnl.gov/"],["Sandia","https://www.sandia.gov/"],["Idaho National Lab","https://inl.gov/"],["Fermilab","https://www.fnal.gov/"],["SLAC","https://www6.slac.stanford.edu/"]];
const categories=["All","Data","Infrastructure","AI models","National challenges","Partnerships"];
let live=[],checkedAt="",liveStatus=[],section="All",mode="All",category="All",limit=12,selectedTier="All";
const escapeHTML=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const safeUrl=url=>{try{const u=new URL(url);return u.protocol==="https:"?u.href:"#"}catch{return"#"}};
const dateText=s=>s&&Number.isFinite(Date.parse(s))?new Date(s).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}):"SOURCE GUIDE";
function allRecords(){const seen=new Set();return [...live,...announcements,...projects,...guides].filter(d=>{const key=d.kind+"|"+d.title.toLowerCase().replace(/[^a-z0-9]/g,"").slice(0,70);if(seen.has(key))return false;seen.add(key);return true})}
function filtered(){const q=$("search").value.toLowerCase().trim();const tokens=q.split(/\s+/).filter(Boolean);return allRecords().filter(d=>{if(mode==="News"&&d.kind!=="news"&&d.kind!=="discovery")return false;if(mode==="Projects"&&d.kind!=="project")return false;if(mode==="Guides"&&d.kind!=="guide")return false;if(section==="News"&&d.kind!=="news"&&d.kind!=="discovery")return false;if(section==="Projects"&&d.kind!=="project")return false;if(section==="Labs"&&!/lab|ornl|argonne|brookhaven|fermilab|sandia|national/i.test((d.source||"")+" "+d.title+" "+(d.organization||"")))return false;if(["Data","AI models","National challenges","Partnerships"].includes(section)&&d.category!==section)return false;if(category!=="All"&&d.category!==category)return false;if(selectedTier!=="All"&&d.tier!==selectedTier)return false;const hay=[d.title,d.summary,d.source,d.organization,d.category,d.tier].join(" ").toLowerCase();return tokens.every(t=>hay.includes(t))}).sort((a,b)=>{const sort=$("sort").value;if(sort==="az")return a.title.localeCompare(b.title);const cmp=(b.date||"").localeCompare(a.date||"");return sort==="old"?-cmp:cmp})}
function showPreview(d){$("previewHint").classList.add("hidden");$("preview").classList.remove("hidden");$("preview").innerHTML='<button class="close-preview" id="clearPreview">✕</button><span class="pill">'+escapeHTML(d.tier)+'</span><span class="pill">'+escapeHTML(d.kind)+'</span><h3>'+escapeHTML(d.title)+'</h3><p>'+escapeHTML(d.summary)+'</p><p class="subtle">Source: '+escapeHTML(d.source)+' · '+escapeHTML(dateText(d.date))+' · '+escapeHTML(d.category)+'</p>'+(d.kind==="discovery"?'<p class="subtle">Automated discovery; verify the original announcement and date before citing.</p>':'')+'<a class="external" href="'+safeUrl(d.url)+'" target="_blank" rel="noopener noreferrer">Open source ↗</a>';$("clearPreview").onclick=()=>{$("preview").classList.add("hidden");$("previewHint").classList.remove("hidden")}}
function render(){const list=filtered();$("recordCount").textContent=String(list.length);$("projectCount").textContent=String(projects.length);$("sourceCount").textContent=String(liveStatus.filter(x=>x.ok).length)+"/3";$("count").textContent=list.length+" matching records · "+(mode==="All"?"all types":mode)+" · "+(category==="All"?"all topics":category);
 $("rows").innerHTML=list.slice(0,limit).map((d,i)=>'<article class="news-item"><div class="meta">'+escapeHTML(dateText(d.date))+'<b>'+escapeHTML(d.source)+'</b></div><div><h3><button data-record="'+i+'">'+escapeHTML(d.title)+'</button></h3><p>'+escapeHTML(d.summary)+'</p><span class="pill">'+escapeHTML(d.tier)+'</span><span class="pill">'+escapeHTML(d.category)+'</span><a href="'+safeUrl(d.url)+'" target="_blank" rel="noopener noreferrer">Source ↗</a></div></article>').join("")||'<div class="empty">No records match. Try a broader search or choose All records.</div>';
 document.querySelectorAll("[data-record]").forEach(b=>b.onclick=()=>showPreview(list[Number(b.dataset.record)]));
 $("more").hidden=list.length<=limit;
 document.querySelectorAll("[data-mode]").forEach(b=>{b.classList.toggle("active",b.dataset.mode===mode);b.setAttribute("aria-pressed",String(b.dataset.mode===mode))});
 document.querySelectorAll("[data-cat]").forEach(b=>{b.classList.toggle("active",b.dataset.cat===category);b.setAttribute("aria-pressed",String(b.dataset.cat===category))});
 document.querySelectorAll("[data-section]").forEach(b=>{b.classList.toggle("active",b.dataset.section===section);b.setAttribute("aria-current",b.dataset.section===section?"page":"false")});
 $("list-title").textContent=section==="All"?"▤ Genesis Intelligence Feed":"▤ "+(section==="Projects"?"Project Tracker":section==="Labs"?"Laboratory Records":section);
}
function setStatus(text,warn=false){$("feedStatus").textContent=text;$("feedStatus").classList.toggle("warn",warn)}
async function fetchLive(force=false){setStatus("Checking latest news-discovery feeds…");$("refresh").disabled=true;try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),14000);let response;try{response=await fetch("/api/news"+(force?"?refresh="+Date.now():""),{signal:controller.signal,cache:force?"reload":"default"})}finally{clearTimeout(timeout)}if(!response.ok)throw new Error("HTTP "+response.status);const data=await response.json();live=Array.isArray(data.items)?data.items.filter(x=>x&&x.title&&safeUrl(x.url)!=="#").map(x=>({...x,kind:"discovery"})):[];liveStatus=Array.isArray(data.sources)?data.sources:[];checkedAt=data.checkedAt||"";const ok=liveStatus.filter(x=>x.ok).length;if(ok){setStatus("Discovery checked "+new Date(checkedAt).toLocaleString()+" · "+live.length+" aggregated headlines · "+ok+" of 3 sources responding. Verify original sources.");$("time").textContent="LATEST CHECK · "+new Date(checkedAt).toLocaleTimeString([], {hour:"numeric",minute:"2-digit"})}else setStatus("Automated feeds unavailable. Showing the curated source archive; these are not live updates.",true)}catch(err){setStatus("Live feed connection unavailable ("+err.message+"). Showing curated records; no automatic updates verified.",true)}finally{$("refresh").disabled=false;render()}}
$("links").innerHTML=labs.map(([name,url])=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(name)+'<span>↗</span></a>').join("");
$("filters").innerHTML=categories.map(c=>'<button class="chip" data-cat="'+escapeHTML(c)+'">'+escapeHTML(c)+'</button>').join("")+'<select id="tier" aria-label="Source classification"><option value="All">All source tiers</option><option value="Official">Official</option><option value="Related">Related</option><option value="Potentially relevant">Potentially relevant</option></select>';
$("spotlights").innerHTML=projects.slice(0,4).map((d,i)=>'<button class="project" data-project="'+i+'"><b>'+escapeHTML(d.title)+'</b><span>'+escapeHTML(d.organization)+'</span></button>').join("");
document.querySelectorAll("[data-project]").forEach(b=>b.onclick=()=>showPreview(projects[+b.dataset.project]));
document.querySelectorAll("[data-section]").forEach(b=>b.onclick=()=>{section=b.dataset.section;mode=section==="News"?"News":section==="Projects"?"Projects":"All";category=section==="Data"?"Data":section==="AI models"?"AI models":section==="National challenges"?"National challenges":section==="Partnerships"?"Partnerships":"All";limit=12;render()});
document.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{mode=b.dataset.mode;section="All";limit=12;render()});
document.querySelectorAll("[data-cat]").forEach(b=>b.onclick=()=>{category=b.dataset.cat;section="All";limit=12;render()});
$("tier").onchange=e=>{selectedTier=e.target.value;limit=12;render()};
$("sort").onchange=render;$("search").oninput=()=>{limit=12;render()};$("more").onclick=()=>{limit+=12;render()};$("refresh").onclick=()=>fetchLive(true);
$("about").onclick=()=>{$("dialogBody").innerHTML='<h2>About Genesis Intelligence</h2><p>Independent public-source intelligence dashboard tracking the U.S. Department of Energy Genesis Mission. Not a DOE website.</p><p><b>Build 2:</b> compact dashboard, client-side searchable curated projects, official source guides, and server-fetched cached news discovery.</p><p><b>Source classifications:</b> Official means DOE-origin information, Related means national-laboratory information, and Potentially relevant means adjacent coverage. Automated discovery is unverified until the original item is checked.</p><p><b>Limits:</b> Project tracker is a selected initial index, not all mission awards. Search runs across currently loaded records, not the entire web. The feed relies on third-party RSS availability and is cached for roughly 30 minutes. No AI assistant or full-text indexing is included yet.</p><p>Office of Synergy / SI is a fictional creative branding element, not a government office.</p>';$("dialog").showModal()};
$("close").onclick=()=>$("dialog").close();render();fetchLive();